import React, { useEffect, useState, useRef } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale,
  PointElement, LineElement, Title, Tooltip, Legend, Filler
} from 'chart.js';
import api from '../../api/axios';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const TYPE_COLORS = {
  temperature: '#f5a623',
  humidite:    '#0099ff',
  courant:     '#00d4aa',
  vibration:   '#ff4757',
};

const TYPE_ICONS = {
  temperature: '🌡️',
  humidite:    '💧',
  courant:     '⚡',
  vibration:   '📳',
};

export default function PageMesures() {
  const [machines, setMachines]         = useState([]);
  const [selectedMachine, setSelected]  = useState(null);
  const [data, setData]                 = useState([]);
  const [loading, setLoading]           = useState(false);
  const [live, setLive]                 = useState(false);
  const liveRef = useRef(null);

  useEffect(() => {
    api.get('/machines').then(r => {
      setMachines(r.data);
      if (r.data.length > 0) selectMachine(r.data[0]);
    });
    return () => stopLive();
  }, []);

  const selectMachine = (machine) => {
    setSelected(machine);
    setLive(false);
    stopLive();
    fetchMesures(machine.id);
  };

  const fetchMesures = (machineId) => {
    setLoading(true);
    api.get(`/mesures?machine_id=${machineId}`).then(r => {
      setData(r.data);
      setLoading(false);
    });
  };

  // Simuler des mesures live
  const startLive = () => {
    setLive(true);
    liveRef.current = setInterval(async () => {
      if (!selectedMachine) return;
      const res = await api.get(`/capteurs`);
      const capteurs = res.data.filter(c => c.machine_id === selectedMachine.id && c.actif);

      for (const capteur of capteurs) {
        const base = {
          temperature: 70, humidite: 45, courant: 12, vibration: 0.5
        }[capteur.type] || 50;
        const valeur = +(base + (Math.random() - 0.5) * 10).toFixed(3);
        await api.post('/mesures', {
          machine_id: selectedMachine.id,
          capteur_id: capteur.id,
          valeur,
        });
      }
      fetchMesures(selectedMachine.id);
    }, 3000);
  };

  const stopLive = () => {
    if (liveRef.current) {
      clearInterval(liveRef.current);
      liveRef.current = null;
    }
    setLive(false);
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
    },
    scales: {
      x: {
        grid:  { color:'rgba(255,255,255,0.04)' },
        ticks: { color:'#4a5260', font:{ family:'monospace', size:10 }, maxTicksLimit:8 },
      },
      y: {
        grid:  { color:'rgba(255,255,255,0.04)' },
        ticks: { color:'#4a5260', font:{ family:'monospace', size:10 } },
      },
    },
  };

  return (
    <div>
      {/* Header */}
      <div style={S.header}>
        <div>
          <div style={S.headerTitle}>Mesures temps réel</div>
          <div style={S.headerSub}>
            {selectedMachine ? selectedMachine.nom : 'Sélectionne une machine'}
          </div>
        </div>
        <div style={{display:'flex', gap:10, alignItems:'center'}}>
          {live && <span style={S.liveDot}/>}
          {!live ? (
            <button style={S.btnLive} onClick={startLive} disabled={!selectedMachine}>
              ▶ Démarrer live
            </button>
          ) : (
            <button style={S.btnStop} onClick={stopLive}>
              ■ Arrêter
            </button>
          )}
        </div>
      </div>

      {/* Sélecteur de machine */}
      <div style={S.machineSelector}>
        {machines.map(m => (
          <button
            key={m.id}
            style={{
              ...S.machineBtn,
              ...(selectedMachine?.id === m.id ? S.machineBtnActive : {})
            }}
            onClick={() => selectMachine(m)}
          >
            {m.nom}
          </button>
        ))}
      </div>

      {loading && <div style={S.loading}>Chargement des mesures...</div>}

      {!loading && data.length === 0 && (
        <div style={S.empty}>
          <div style={{fontSize:32, marginBottom:12}}>📊</div>
          <div>Aucune mesure disponible pour cette machine</div>
          <div style={{fontSize:12, color:'#4a5260', marginTop:8}}>
            Démarre le mode live pour générer des mesures simulées
          </div>
        </div>
      )}

      {/* Graphiques */}
      {!loading && data.map(item => {
        if (!item.mesures || item.mesures.length === 0) return null;
        const color  = TYPE_COLORS[item.capteur.type] || '#00d4aa';
        const labels = item.mesures.map(m =>
          new Date(m.horodatage).toTimeString().slice(0, 8)
        );
        const values = item.mesures.map(m => parseFloat(m.valeur));
        const derniere = item.derniere ? parseFloat(item.derniere.valeur).toFixed(3) : '—';
        const horseSeuil = item.derniere?.hors_seuil;

        const chartData = {
          labels,
          datasets: [{
            data:            values,
            borderColor:     color,
            backgroundColor: color + '15',
            borderWidth:     1.5,
            pointRadius:     0,
            tension:         0.4,
            fill:            true,
          }]
        };

        return (
          <div key={item.capteur.id} style={S.chartCard}>
            <div style={S.chartHead}>
              <div style={{display:'flex', alignItems:'center', gap:10}}>
                <span style={{fontSize:20}}>{TYPE_ICONS[item.capteur.type]}</span>
                <div>
                  <div style={S.chartTitle}>{item.capteur.type.toUpperCase()}</div>
                  <div style={S.chartSub}>Unité : {item.capteur.unite}</div>
                </div>
              </div>
              <div style={{textAlign:'right'}}>
                <div style={{...S.chartVal, color: horseSeuil ? '#ff4757' : color}}>
                  {derniere} {item.capteur.unite}
                </div>
                {horseSeuil ? (
                  <span style={S.horseSeuil}>⚠ HORS SEUIL</span>
                ) : (
                  <span style={S.normal}>✓ Normal</span>
                )}
              </div>
            </div>

            {/* Seuils */}
            {(item.capteur.seuil_min !== null || item.capteur.seuil_max !== null) && (
              <div style={S.seuilsRow}>
                <span style={S.seuilTag}>
                  MIN : {item.capteur.seuil_min ?? '—'} {item.capteur.unite}
                </span>
                <span style={S.seuilTag}>
                  MAX : {item.capteur.seuil_max ?? '—'} {item.capteur.unite}
                </span>
                <span style={S.seuilTag}>
                  {item.mesures.length} mesure(s)
                </span>
              </div>
            )}

            {/* Graphique */}
            <div style={{height:180}}>
              <Line data={chartData} options={chartOptions} />
            </div>
          </div>
        );
      })}
    </div>
  );
}

